begin;
create extension if not exists pgtap with schema extensions;
select plan(34);
select has_table('public', 'employees', 'staff table exists');
select has_table('private', 'employee_auth', 'Auth mapping is private');
-- Fixtures are synthetic and rolled back; real auth.sessions are used for expiry checks.
insert into auth.users(id) select ('00000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,4) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('10000000-0000-0000-0000-00000000000' || n)::uuid, ('00000000-0000-0000-0000-00000000000' || n)::uuid, now(), now() from generate_series(1,4) n;
insert into public.employees(id,employee_code,display_name,role) values
 ('20000000-0000-0000-0000-000000000001','GM','General','general_manager'),
 ('20000000-0000-0000-0000-000000000002','MGR','Manager','manager'),
 ('20000000-0000-0000-0000-000000000003','READ','Reader','employee'),
 ('20000000-0000-0000-0000-000000000004','NONE','None','employee');
insert into private.employee_auth(employee_id,auth_user_id) select ('20000000-0000-0000-0000-00000000000' || n)::uuid, ('00000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,4) n;
insert into public.employee_permissions(employee_id,cases_read) values ('20000000-0000-0000-0000-000000000003',true);
select throws_ok($$insert into public.employees(employee_code,display_name) values ('READ','Duplicate')$$,'23505',null,'employee codes are unique');
-- Contract fixtures: later domain migrations must attach these exact policy helpers.
create table public.test_cases(id int); create table public.test_donations(id int);
insert into public.test_cases values (1); insert into public.test_donations values (1);
alter table public.test_cases enable row level security; alter table public.test_donations enable row level security;
grant select,insert,update,delete on public.test_cases,public.test_donations to authenticated;
create policy cases_read on public.test_cases for select to authenticated using (public.has_permission('casesRead'));
create policy cases_write on public.test_cases for insert to authenticated with check (public.has_permission('casesWrite'));
create policy cases_update on public.test_cases for update to authenticated using(public.has_permission('casesWrite')) with check(public.has_permission('casesWrite'));
create policy donations_write on public.test_donations for insert to authenticated with check(public.has_permission('donationsWrite'));
create policy donations_update on public.test_donations for update to authenticated using(public.has_permission('donationsWrite')) with check(public.has_permission('donationsWrite'));
create policy donations_read on public.test_donations for select to authenticated using (public.has_permission('donationsRead'));
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"10000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.test_cases),1,'reader sees cases');
select is((select count(*)::int from public.test_donations),0,'reader cannot see donations');
select throws_ok($$insert into public.test_cases values (2)$$,'42501',null,'reader cannot write cases');
with changed as (update public.test_cases set id=2 returning id) select is((select count(*)::int from changed),0,'reader cannot update case rows');
select throws_ok($$insert into public.test_donations values (2)$$,'42501',null,'no donation permission cannot insert');
with changed as (update public.test_donations set id=2 returning id) select is((select count(*)::int from changed),0,'no donation permission cannot update');
select throws_ok($$select public.set_employee_permissions('20000000-0000-0000-0000-000000000003','{"casesWrite":true}')$$,'42501',null,'employee cannot grant own permissions');
select throws_ok($$select * from private.employee_auth$$,'42501',null,'mapping unavailable to employee');
select throws_ok($$update public.employees set role='general_manager'$$,'42501',null,'direct privilege escalation blocked');
select throws_ok($$select public.deactivate_employee('20000000-0000-0000-0000-000000000002')$$,'42501',null,'employee cannot deactivate');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","session_id":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select ok(public.has_permission('casesWrite') and public.has_permission('donationsWrite') and public.has_permission('assistantUse'),'manager role grants');
with changed as (update public.test_cases set id=2 returning id) select is((select count(*)::int from changed),1,'manager can update case rows');
with changed as (update public.test_donations set id=2 returning id) select is((select count(*)::int from changed),1,'manager can update donation rows');
select lives_ok($$insert into public.test_cases values (3)$$,'manager can insert case rows');
select lives_ok($$insert into public.test_donations values (3)$$,'manager can insert donation rows');
select lives_ok($$select public.set_employee_permissions('20000000-0000-0000-0000-000000000004','{"assistantUse":true}')$$,'manager may edit employee permissions');
select throws_ok($$select public.set_employee_permissions('20000000-0000-0000-0000-000000000001','{}')$$,'42501',null,'manager cannot edit general manager permissions');
select throws_ok($$select public.deactivate_employee('20000000-0000-0000-0000-000000000003')$$,'42501',null,'manager cannot deactivate');
select throws_ok($$select public.register_employee('00000000-0000-0000-0000-000000000004','BAD','Bad','manager','{}')$$,'42501',null,'manager cannot create manager');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select ok(public.has_permission('casesWrite') and public.has_permission('donationsWrite') and public.has_permission('assistantUse'),'general manager role grants');
select lives_ok($$select public.deactivate_employee('20000000-0000-0000-0000-000000000003')$$,'general manager can deactivate');
reset role;
select is((select count(*)::int from public.employees where employee_code='READ'),1,'deactivation retains history');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"10000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select ok(not public.has_permission('casesRead'),'deactivated session denied immediately');
select is((select count(*)::int from public.test_cases),0,'deactivated session cannot read actual rows');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","session_id":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
update auth.sessions set created_at=now()-interval '30 days', refreshed_at=now() where user_id='00000000-0000-0000-0000-000000000002';
set local role authenticated;
select ok(not public.has_permission('casesRead'),'refresh cannot extend 30 day deadline');
select is((select count(*)::int from public.test_donations),0,'expired session cannot read actual rows');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.revoke_staff_session()$$,'logout revokes current session');
select ok(not public.has_permission('casesRead'),'same JWT denied after logout');
select throws_ok($$insert into public.test_cases values (4)$$,'42501',null,'revoked JWT cannot insert actual rows');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000004","session_id":"10000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.test_cases),0,'unprivileged employee sees no cases');
select is((select count(*)::int from public.test_donations),0,'unprivileged employee sees no donations');
select * from finish(); rollback;
